//! The classes and case folds of the bytes past ASCII in every single-byte
//! encoding Ruby has, as its regexps answer them (#372). Do not edit by hand.
//!
//! Generated by `scripts/regexp-oracle.rb --generate`, from the same
//! measurement as `tests/encodings.txt`; CI re-runs it with `--check`, and
//! the unit test that replays that file checks these tables against it.
//! Measured rather than derived from Unicode: Onigmo's tables are its own,
//! and differ from Unicode's even for ISO-8859-1.

use crate::Encoding;

/// A single-byte encoding with classes or case folds past ASCII, named for
/// the first encoding in CRuby's index order to measure as it does.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Charset {
    Iso8859_1,
    Iso8859_2,
    Iso8859_3,
    Iso8859_4,
    Iso8859_5,
    Iso8859_6,
    Iso8859_7,
    Iso8859_8,
    Iso8859_9,
    Iso8859_10,
    Iso8859_11,
    Iso8859_13,
    Iso8859_14,
    Iso8859_15,
    Iso8859_16,
    Koi8R,
    Koi8U,
    Windows1250,
    Windows1251,
    Windows1252,
    Windows1253,
    Windows1254,
}

/// One encoding's bytes past ASCII. A class has bit `b - 0x80` set for each
/// byte `b` it holds.
pub(crate) struct Table {
    pub(crate) alpha: u128,
    pub(crate) digit: u128,
    pub(crate) alnum: u128,
    pub(crate) upper: u128,
    pub(crate) lower: u128,
    pub(crate) space: u128,
    pub(crate) blank: u128,
    pub(crate) print: u128,
    pub(crate) graph: u128,
    pub(crate) cntrl: u128,
    pub(crate) xdigit: u128,
    pub(crate) word: u128,
    pub(crate) ascii: u128,
    pub(crate) punct: u128,
    pub(crate) perl_word: u128,
    pub(crate) perl_digit: u128,
    pub(crate) perl_space: u128,
    pub(crate) perl_hex: u128,
    pub(crate) word_boundary: u128,
    /// `(x, y)` for each pair `/x/i` matches, past ASCII's own cases, in
    /// ascending order. Not symmetric, and a pair can have one ASCII side.
    pub(crate) folds: &'static [(u8, u8)],
    /// The same for a class of more than one character, whose folds Onigmo
    /// takes from another map: `/[xz]/i` matches `y` when `(x, y)` or
    /// `(z, y)` is here.
    pub(crate) class_folds: &'static [(u8, u8)],
}

impl Charset {
    pub(crate) fn table(self) -> &'static Table {
        match self {
            Charset::Iso8859_1 => &ISO_8859_1,
            Charset::Iso8859_2 => &ISO_8859_2,
            Charset::Iso8859_3 => &ISO_8859_3,
            Charset::Iso8859_4 => &ISO_8859_4,
            Charset::Iso8859_5 => &ISO_8859_5,
            Charset::Iso8859_6 => &ISO_8859_6,
            Charset::Iso8859_7 => &ISO_8859_7,
            Charset::Iso8859_8 => &ISO_8859_8,
            Charset::Iso8859_9 => &ISO_8859_9,
            Charset::Iso8859_10 => &ISO_8859_10,
            Charset::Iso8859_11 => &ISO_8859_11,
            Charset::Iso8859_13 => &ISO_8859_13,
            Charset::Iso8859_14 => &ISO_8859_14,
            Charset::Iso8859_15 => &ISO_8859_15,
            Charset::Iso8859_16 => &ISO_8859_16,
            Charset::Koi8R => &KOI8_R,
            Charset::Koi8U => &KOI8_U,
            Charset::Windows1250 => &WINDOWS_1250,
            Charset::Windows1251 => &WINDOWS_1251,
            Charset::Windows1252 => &WINDOWS_1252,
            Charset::Windows1253 => &WINDOWS_1253,
            Charset::Windows1254 => &WINDOWS_1254,
        }
    }
}

/// How the engine reads a single-byte encoding, by its name: as BINARY when
/// Onigmo classes and folds nothing past ASCII in it, else by its table.
#[rustfmt::skip]
pub(crate) fn reading(name: &str) -> Option<Encoding> {
    Some(match name {
        "ASCII-8BIT" | "IBM437" | "IBM720" | "IBM737" | "IBM775" | "CP850" | "IBM852" | "CP852" | "IBM855" | "CP855" | "IBM857" | "IBM860" | "IBM861" | "IBM862" | "IBM863" | "IBM864" | "IBM865" | "IBM866" | "IBM869" | "Windows-1258" | "GB1988" | "macCentEuro" | "macCroatian" | "macCyrillic" | "macGreek" | "macIceland" | "macRoman" | "macRomania" | "macThai" | "macTurkish" | "macUkraine" => Encoding::Binary,
        "ISO-8859-1" => Encoding::Single(Charset::Iso8859_1),
        "ISO-8859-2" => Encoding::Single(Charset::Iso8859_2),
        "ISO-8859-3" => Encoding::Single(Charset::Iso8859_3),
        "ISO-8859-4" => Encoding::Single(Charset::Iso8859_4),
        "ISO-8859-5" => Encoding::Single(Charset::Iso8859_5),
        "ISO-8859-6" | "Windows-1256" => Encoding::Single(Charset::Iso8859_6),
        "ISO-8859-7" => Encoding::Single(Charset::Iso8859_7),
        "ISO-8859-8" | "Windows-1255" => Encoding::Single(Charset::Iso8859_8),
        "ISO-8859-9" => Encoding::Single(Charset::Iso8859_9),
        "ISO-8859-10" => Encoding::Single(Charset::Iso8859_10),
        "ISO-8859-11" | "TIS-620" | "Windows-874" => Encoding::Single(Charset::Iso8859_11),
        "ISO-8859-13" | "Windows-1257" => Encoding::Single(Charset::Iso8859_13),
        "ISO-8859-14" => Encoding::Single(Charset::Iso8859_14),
        "ISO-8859-15" => Encoding::Single(Charset::Iso8859_15),
        "ISO-8859-16" => Encoding::Single(Charset::Iso8859_16),
        "KOI8-R" => Encoding::Single(Charset::Koi8R),
        "KOI8-U" => Encoding::Single(Charset::Koi8U),
        "Windows-1250" => Encoding::Single(Charset::Windows1250),
        "Windows-1251" => Encoding::Single(Charset::Windows1251),
        "Windows-1252" => Encoding::Single(Charset::Windows1252),
        "Windows-1253" => Encoding::Single(Charset::Windows1253),
        "Windows-1254" => Encoding::Single(Charset::Windows1254),
        _ => return None,
    })
}

